        resourcesMenu.classList.remove("open");
        productsBtn.setAttribute("aria-expanded", String(open));
        resourcesBtn.setAttribute("aria-expanded", "false");
      } else {
        const open = resourcesMenu.classList.toggle("open");
        productsMenu.classList.remove("open");
        resourcesBtn.setAttribute("aria-expanded", String(open));
        productsBtn.setAttribute("aria-expanded", "false");
      }
    }

