      el.addEventListener("mouseenter", () => {
        productsMenu.classList.add("open");
        resourcesMenu.classList.remove("open");
        productsBtn.setAttribute("aria-expanded", "true");
        resourcesBtn.setAttribute("aria-expanded", "false");
      });
    });

    [resourcesBtn, resourcesMenu].forEach(el => {
      el.addEventListener("mouseenter", () => {
        resourcesMenu.classList.add("open");
        productsMenu.classList.remove("open");
        resourcesBtn.setAttribute("aria-expanded", "true");
        productsBtn.setAttribute("aria-expanded", "false");
      });
    });

