          ` : ""}
          <div class="author"><span class="avatar">${post.initials}</span> ${post.author}</div>
        </article>
      `).join("");
    }

    function filteredPosts() {
      return allPosts.filter(post => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const q = query.trim().toLowerCase();
        const searchMatch = !q || [post.title, post.excerpt, post.author, post.category].join(" ").toLowerCase().includes(q);
        return categoryMatch && searchMatch;
      });
    }

    function renderPills() {
      categoryPills.innerHTML = categories.map(category => `
        <button type="button" class="pill ${category === activeCategory ? "active" : ""}" data-category="${category}" aria-pressed="${category === activeCategory}">${category}</button>
