      showMoreBtn.style.display = posts.length > visible.length ? "inline-flex" : "none";

      const summaryCategory = activeCategory === "All Posts" ? "all categories" : activeCategory;
      resultMeta.textContent = posts.length
        ? `Showing ${visible.length} of ${posts.length} posts in ${summaryCategory}`
        : `Showing 0 posts in ${summaryCategory}`;
    }

    showMoreBtn.addEventListener("click", () => {
      visibleCount += increment;
      renderLatest();
    });

    searchInput.addEventListener("input", (e) => {
      query = e.target.value;
      visibleCount = 6;
      renderLatest();
    });

    renderFeatured();
    renderPills();
    renderLatest();
