  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        category: "Engineering",
        date: "Apr 10, 2026",
        title: "Agentic Infrastructure: How coding agents now initiate 30% of DeployCloud deployments",
        excerpt: "The share of deployments initiated by coding agents has climbed to 30%—a 1000% increase from six months ago—while agent-led projects are now 20x more likely to call AI inference services.",
        author: "Maya Chen",
        initials: "MC",
        stats: [
          { value: "30%", label: "Deployments agent-initiated" },
          { value: "1000%", label: "Growth in six months" },
          { value: "20x", label: "More likely AI inference" }
        ]
      },
      {
        category: "Engineering",
        date: "Apr 3, 2026",
        title: "A new programming model for durable execution",
        excerpt: "Durable execution changes how teams compose resilient workflows across deployments, retries, and long-running tasks.",
        author: "Alex Rivera",
        initials: "AR"
      },
      {
        category: "Security",
        date: "Mar 28, 2026",
        title: "Agent responsibly",
        excerpt: "Secure design patterns for autonomous systems, including policy boundaries, runtime verification, and safer defaults.",
        author: "Nina Patel",
        initials: "NP"
      }
    ];

    const allPosts = [
      { category: "Engineering", date: "Apr 3, 2026", title: "A new programming model for durable execution", excerpt: "Build fault-tolerant, resumable workloads with less operational complexity.", author: "Alex Rivera", initials: "AR" },
      { category: "Security", date: "Mar 26, 2026", title: "Zero Data Retention on AI Gateway", excerpt: "How DeployCloud enforces stronger privacy boundaries for regulated workflows.", author: "Nina Patel", initials: "NP" },
      { category: "Engineering", date: "Mar 21, 2026", title: "Optimizing Sandbox snapshots", excerpt: "Smarter snapshotting reduced cold starts and improved developer iteration loops.", author: "Liam Brooks", initials: "LB" },
      { category: "Customers", date: "Mar 18, 2026", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A customer story about balancing readability, crawlability, and agent discoverability.", author: "Eva Gomez", initials: "EG" },
      { category: "Engineering", date: "Mar 12, 2026", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "Hybrid collaboration patterns that moved build performance from bottleneck to edge.", author: "Jon Park", initials: "JP" },
      { category: "Company News", date: "Mar 6, 2026", title: "Unified reporting for all AI Gateway usage", excerpt: "Track requests, latency, and spend across every model provider in one dashboard.", author: "Priya Shah", initials: "PS" },
      { category: "Community", date: "Feb 28, 2026", title: "Community release notes: spring platform updates", excerpt: "What shipped this month across DX, observability, and deployment tooling.", author: "Noah Kim", initials: "NK" },
      { category: "Customers", date: "Feb 20, 2026", title: "How teams scale platform engineering with DeployCloud", excerpt: "A practical look at multi-team governance and deployment autonomy.", author: "Sara Ali", initials: "SA" },
      { category: "Security", date: "Feb 14, 2026", title: "BotID and adaptive protection in modern apps", excerpt: "Hardening production surfaces without slowing down trusted traffic.", author: "Drew Lee", initials: "DL" },
      { category: "Company News", date: "Feb 10, 2026", title: "DeployCloud Enterprise product tour now live", excerpt: "Explore advanced controls, tenant isolation, and custom support workflows.", author: "Mia Stone", initials: "MS" },
      { category: "Engineering", date: "Feb 3, 2026", title: "Observability patterns for edge-first systems", excerpt: "Tracing deployments and runtime behavior from commit to production.", author: "Omar Diaz", initials: "OD" },
      { category: "Community", date: "Jan 29, 2026", title: "Inside the DeployCloud developer community", excerpt: "Events, discussions, and open-source contributions from global teams.", author: "Iris Bell", initials: "IB" }
    ];

    let activeCategory = "All Posts";
    let query = "";
    let visibleCount = 6;
    const increment = 3;

    const featuredGrid = document.getElementById("featuredGrid");
    const latestGrid = document.getElementById("latestGrid");
    const categoryPills = document.getElementById("categoryPills");
    const searchInput = document.getElementById("searchInput");
    const emptyState = document.getElementById("emptyState");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const resultMeta = document.getElementById("resultMeta");

    const productsBtn = document.getElementById("productsBtn");
    const resourcesBtn = document.getElementById("resourcesBtn");
    const productsMenu = document.getElementById("productsMenu");
    const resourcesMenu = document.getElementById("resourcesMenu");

    const closeMenus = () => {
      productsMenu.classList.remove("open");
      resourcesMenu.classList.remove("open");
      productsBtn.setAttribute("aria-expanded", "false");
      resourcesBtn.setAttribute("aria-expanded", "false");
    };

    function toggleMenu(which) {
      if (which === "products") {
        const open = productsMenu.classList.toggle("open");
        resourcesMenu.classList.remove("open");
        productsBtn.setAttribute("aria-expanded", String(open));
        resourcesBtn.setAttribute("aria-expanded", "false");
      } else {
        const open = resourcesMenu.classList.toggle("open");
        productsMenu.classList.remove("open");
        resourcesBtn.setAttribute("aria-expanded", String(open));
        productsBtn.setAttribute("aria-expanded", "false");
      }
    }

    productsBtn.addEventListener("click", () => toggleMenu("products"));
    resourcesBtn.addEventListener("click", () => toggleMenu("resources"));

    [productsBtn, productsMenu].forEach(el => {
      el.addEventListener("mouseenter", () => {
        productsMenu.classList.add("open");
        resourcesMenu.classList.remove("open");
        productsBtn.setAttribute("aria-expanded", "true");
        resourcesBtn.setAttribute("aria-expanded", "false");
      });
    });

    [resourcesBtn, resourcesMenu].forEach(el => {
      el.addEventListener("mouseenter", () => {
        resourcesMenu.classList.add("open");
        productsMenu.classList.remove("open");
        resourcesBtn.setAttribute("aria-expanded", "true");
        productsBtn.setAttribute("aria-expanded", "false");
      });
    });

    document.addEventListener("click", (e) => {
      const insideNav = e.target.closest(".nav");
      if (!insideNav) closeMenus();
    });

    function renderFeatured() {
      featuredGrid.innerHTML = featuredPosts.map((post, index) => `
        <article class="card featured-card">
          <div><span class="tag">${post.category}</span><span class="date">${post.date}</span></div>
          <h3>${post.title}</h3>
          <p>${post.excerpt}</p>
          ${index === 0 ? `
            <div class="stats" aria-label="Agentic infrastructure stats">
              ${post.stats.map(s => `<div class="stat"><strong>${s.value}</strong><span>${s.label}</span></div>`).join("")}
            </div>
          ` : ""}
          <div class="author"><span class="avatar">${post.initials}</span> ${post.author}</div>
        </article>
      `).join("");
    }

    function filteredPosts() {
      return allPosts.filter(post => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const q = query.trim().toLowerCase();
        const searchMatch = !q || [post.title, post.excerpt, post.author, post.category].join(" ").toLowerCase().includes(q);
        return categoryMatch && searchMatch;
      });
    }

    function renderPills() {
      categoryPills.innerHTML = categories.map(category => `
        <button type="button" class="pill ${category === activeCategory ? "active" : ""}" data-category="${category}" aria-pressed="${category === activeCategory}">${category}</button>
      `).join("");

      categoryPills.querySelectorAll(".pill").forEach(btn => {
        btn.addEventListener("click", () => {
          activeCategory = btn.dataset.category;
          visibleCount = 6;
          renderPills();
          renderLatest();
        });
      });
    }

    function renderLatest() {
      const posts = filteredPosts();
      const visible = posts.slice(0, visibleCount);

      latestGrid.innerHTML = visible.map(post => `
        <article class="card news-card" aria-label="${post.title}">
          <div><span class="tag">${post.category}</span><span class="date">${post.date}</span></div>
          <h3>${post.title}</h3>
          <p>${post.excerpt}</p>
          <div class="author"><span class="avatar">${post.initials}</span> ${post.author}</div>
        </article>
      `).join("");

      emptyState.style.display = posts.length ? "none" : "block";
      showMoreBtn.style.display = posts.length > visible.length ? "inline-flex" : "none";

      const summaryCategory = activeCategory === "All Posts" ? "all categories" : activeCategory;
      resultMeta.textContent = posts.length
        ? `Showing ${visible.length} of ${posts.length} posts in ${summaryCategory}`
        : `Showing 0 posts in ${summaryCategory}`;
    }

    showMoreBtn.addEventListener("click", () => {
      visibleCount += increment;
      renderLatest();
    });

    searchInput.addEventListener("input", (e) => {
      query = e.target.value;
      visibleCount = 6;
      renderLatest();
    });

    renderFeatured();
    renderPills();
    renderLatest();
  </script>
</body>
